INSERT INTO marker (id, submap_id, overlay_id, marker_status_id, marker_category_id, user_id, name, description, x, y, z, jump_marker_id, global, path, game_data, visible, last_updated) SELECT 9000048, 90001, NULL, 2, 9006, COALESCE((SELECT id FROM user WHERE id = 15), 1), 'Trade 1: Mushroom', '', 40, -200, NULL, 0, 0, '', NULL, 1, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker WHERE id = 9000048);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 9000048, 2, COALESCE((SELECT id FROM user WHERE id = 15), 1), '', '&lt;p&gt;&lt;img src=&quot;images/pathlab/trade-1.webp&quot; alt=&quot;The desert ledge where the mushroom grows&quot; width=&quot;640&quot; height=&quot;360&quot;&gt;&lt;/p&gt;&lt;p&gt;Start the sequence on the high ledge in the desert. A &lt;strong&gt;Mushroom&lt;/strong&gt; grows in the patch of grass beside the cave. Pick it up before you talk to anyone else: nobody will trade with you until you have it.&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 9000048);
INSERT INTO marker (id, submap_id, overlay_id, marker_status_id, marker_category_id, user_id, name, description, x, y, z, jump_marker_id, global, path, game_data, visible, last_updated) SELECT 9000049, 90001, NULL, 2, 9006, COALESCE((SELECT id FROM user WHERE id = 15), 1), 'Trade 2: Powder', '', 62, -150, NULL, 0, 0, '', NULL, 1, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker WHERE id = 9000049);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 9000049, 2, COALESCE((SELECT id FROM user WHERE id = 15), 1), '', '&lt;p&gt;&lt;img src=&quot;images/pathlab/trade-2.webp&quot; alt=&quot;The witch&#39;s hut by the river&quot; width=&quot;640&quot; height=&quot;360&quot;&gt;&lt;/p&gt;&lt;p&gt;Bring the Mushroom to the hut by the river. Leave the area and come back, and it will have been brewed into &lt;strong&gt;Magic Powder&lt;/strong&gt;.&lt;/p&gt;&lt;p&gt;Tip: the powder also has a use of its own, so don&#39;t worry about running out. The trade only needs one sprinkle.&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 9000049);
INSERT INTO marker (id, submap_id, overlay_id, marker_status_id, marker_category_id, user_id, name, description, x, y, z, jump_marker_id, global, path, game_data, visible, last_updated) SELECT 9000050, 90001, NULL, 2, 9006, COALESCE((SELECT id FROM user WHERE id = 15), 1), 'Trade 3: Letter', '', 95, -120, NULL, 0, 0, '', NULL, 1, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker WHERE id = 9000050);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 9000050, 2, COALESCE((SELECT id FROM user WHERE id = 15), 1), '', '&lt;p&gt;&lt;img src=&quot;images/pathlab/trade-3.webp&quot; alt=&quot;The village south of the castle&quot; width=&quot;640&quot; height=&quot;360&quot;&gt;&lt;/p&gt;&lt;p&gt;Sprinkle the Powder in front of the village elder&#39;s house. In thanks, the elder hands over a sealed &lt;strong&gt;Letter&lt;/strong&gt; addressed to someone across the bridge.&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 9000050);
INSERT INTO marker (id, submap_id, overlay_id, marker_status_id, marker_category_id, user_id, name, description, x, y, z, jump_marker_id, global, path, game_data, visible, last_updated) SELECT 9000051, 90001, NULL, 2, 9006, COALESCE((SELECT id FROM user WHERE id = 15), 1), 'Trade 4: Broom', '', 140, -92, NULL, 0, 0, '', NULL, 1, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker WHERE id = 9000051);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 9000051, 2, COALESCE((SELECT id FROM user WHERE id = 15), 1), '', '&lt;p&gt;&lt;img src=&quot;images/pathlab/trade-4.webp&quot; alt=&quot;The sweeper&#39;s house east of the castle&quot; width=&quot;640&quot; height=&quot;360&quot;&gt;&lt;/p&gt;&lt;p&gt;This is the longest step of the sequence, and the easiest to get stuck on. The Letter is for the sweeper who lives east of the castle, but they only answer the door at certain times, and the path there changes once you&#39;ve opened the castle gate.&lt;/p&gt;&lt;h4&gt;Getting there&lt;/h4&gt;&lt;p&gt;From the village, follow the river east until it bends north. Cross at the wooden bridge (not the stone one: the stone one leads you back toward the castle moat). Past the bridge, the road splits three ways.&lt;/p&gt;&lt;ul&gt;&lt;li&gt;The &lt;strong&gt;left&lt;/strong&gt; fork climbs toward the castle&#39;s outer wall. It&#39;s a dead end until much later.&lt;/li&gt;&lt;li&gt;The &lt;strong&gt;middle&lt;/strong&gt; fork leads to a field of tall grass. Cutting it reveals a few rupees, but nothing for the trade.&lt;/li&gt;&lt;li&gt;The &lt;strong&gt;right&lt;/strong&gt; fork is the one you want. It winds past two boulders and a signpost before reaching the house.&lt;/li&gt;&lt;/ul&gt;&lt;p&gt;&lt;img src=&quot;images/pathlab/trade-4b.webp&quot; alt=&quot;The road east, past the bridge&quot; width=&quot;640&quot; height=&quot;360&quot;&gt;&lt;/p&gt;&lt;h4&gt;At the house&lt;/h4&gt;&lt;p&gt;Knock during the day. If the house is dark, rest at the inn and come back: the sweeper keeps to a strict schedule and won&#39;t open up after sunset, no matter how many times you knock.&lt;/p&gt;&lt;p&gt;Hand over the Letter and the sweeper will read it twice, sigh, and give you their old &lt;strong&gt;Broom&lt;/strong&gt;. They mention that the broom has been in the family for generations, and that the fisherman by the lake has been asking about it for years.&lt;/p&gt;&lt;p&gt;&lt;img src=&quot;images/pathlab/trade-4c.webp&quot; alt=&quot;The lake shore, seen from the sweeper&#39;s porch&quot; width=&quot;640&quot; height=&quot;360&quot;&gt;&lt;/p&gt;&lt;h4&gt;If you miss it&lt;/h4&gt;&lt;p&gt;Lost the Broom? You can&#39;t get a second one from the sweeper, but the fisherman will still accept the trade later if you bring back the Letter instead. It&#39;s slower: you&#39;ll have to repeat the last two steps. This note exists mostly so that this step is long enough to test how the path page cuts long marker text short and lets you expand it.&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 9000051);
INSERT INTO marker (id, submap_id, overlay_id, marker_status_id, marker_category_id, user_id, name, description, x, y, z, jump_marker_id, global, path, game_data, visible, last_updated) SELECT 9000052, 90001, NULL, 2, 9006, COALESCE((SELECT id FROM user WHERE id = 15), 1), 'Trade 5: Fishing Hook', '', 182, -110, NULL, 0, 0, '', NULL, 1, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker WHERE id = 9000052);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 9000052, 2, COALESCE((SELECT id FROM user WHERE id = 15), 1), '', '&lt;p&gt;&lt;img src=&quot;images/pathlab/trade-5.webp&quot; alt=&quot;The fisherman&#39;s dock on the lake&quot; width=&quot;640&quot; height=&quot;360&quot;&gt;&lt;/p&gt;&lt;p&gt;The fisherman on the dock trades the Broom for a &lt;strong&gt;Fishing Hook&lt;/strong&gt;. Talk to them twice: the first time, they only talk about the weather.&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 9000052);
INSERT INTO marker (id, submap_id, overlay_id, marker_status_id, marker_category_id, user_id, name, description, x, y, z, jump_marker_id, global, path, game_data, visible, last_updated) SELECT 9000053, 90001, NULL, 2, 9006, COALESCE((SELECT id FROM user WHERE id = 15), 1), 'Trade 6: Necklace', '', 210, -160, NULL, 0, 0, '', NULL, 1, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker WHERE id = 9000053);
INSERT INTO marker_tab (marker_id, marker_tab_status_id, user_id, tab_title, tab_text, tab_order, visible) SELECT 9000053, 2, COALESCE((SELECT id FROM user WHERE id = 15), 1), '', '&lt;p&gt;&lt;img src=&quot;images/pathlab/trade-6.webp&quot; alt=&quot;The cliffside cave in the east&quot; width=&quot;640&quot; height=&quot;360&quot;&gt;&lt;/p&gt;&lt;p&gt;Climb to the cave in the eastern cliffs. The collector inside wants the Fishing Hook and gives you a &lt;strong&gt;Necklace&lt;/strong&gt; in return.&lt;/p&gt;', 1, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker_tab WHERE marker_id = 9000053);
INSERT INTO marker (id, submap_id, overlay_id, marker_status_id, marker_category_id, user_id, name, description, x, y, z, jump_marker_id, global, path, game_data, visible, last_updated) SELECT 9000054, 90001, NULL, 2, 9006, COALESCE((SELECT id FROM user WHERE id = 15), 1), 'Trade 7: Scale', '', 190, -212, NULL, 0, 0, '', NULL, 1, NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM marker WHERE id = 9000054);
